pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address caller, uint256 firstVal, uint256 secondVal) public {
        vm.assume(caller != address(0));

        vm.prank(caller);
        c.SetMinSum(firstVal);

        vm.prank(caller);
        c.SetMinSum(secondVal);

        assertTrue(c.MinSum() == secondVal);
    }
}
